window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-55502a56dea0160b"]={"versions": [{"id": "FIG-55502a56dea0160b", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm PduR</code>) zur Spezifikation des Zustandsmodells des AUTOSAR PDU Routers (PduR) im Schichtenmodell der AUTOSAR-Basissoftware (Communication Services). Es modelliert die Lebenszyklus- und Betriebsmodi der Komponente von der Systeminitialisierung bis zum Herunterfahren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält folgende Modellelemente:</p>\n<ul class=\"fig-list\">\n<li>Startzustand: <code>Powerup</code> (Initial-Pseudozustand)</li>\n<li>Zustände:</li>\n<li><code>PDUR_UNINIT</code>: Initialer Zustand nach dem Einschalten, uninitialisierter Zustand des Moduls</li>\n<li><code>PDUR_ONLINE</code>: Regulärer Betriebsmodus für volles Routing</li>\n<li><code>PDUR_REDUCED</code>: Eingeschränkter Betriebsmodus nach fehlerhafter Initialisierung</li>\n<li>Endzustand: <code>PowerDown</code> (Endzustand / System-Terminierung)</li>\n<li>Schnittstellen und Trigger:</li>\n<li>Initialisierungsfunktion <code>PduR_Init(ConfigPtr)</code> mit Fehlerunterscheidung (<code>without error</code>, <code>with error</code>)</li>\n<li>Ereignis <code>Shutdown</code></li>\n<li>Unmittelbarer Übergang <code>immediate</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss verläuft deterministisch über folgende Pfade:</p>\n<ol class=\"fig-list\">\n<li>Ausgehend von <code>Powerup</code> wechselt der PduR über den Übergang <code>immediate</code> direkt in den Zustand <code>PDUR_UNINIT</code>.</li>\n<li>Aus <code>PDUR_UNINIT</code> erfolgt der Aufruf von <code>PduR_Init(ConfigPtr)</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei fehlerfreier Initialisierung (<code>without error</code>) wechselt der PduR in den Zustand <code>PDUR_ONLINE</code>.</li>\n<li>Bei Auftreten eines Fehlers (<code>with error</code>) wechselt der PduR in den Zustand <code>PDUR_REDUCED</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Aus jedem der drei operativen Zustände (<code>PDUR_ONLINE</code>, <code>PDUR_UNINIT</code>, <code>PDUR_REDUCED</code>) führt ein auslösendes <code>Shutdown</code>-Ereignis direkt in den Endzustand <code>PowerDown</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindendes Zustandsverhalten für die Implementierung des AUTOSAR PDU Routers:</p>\n<ul class=\"fig-list\">\n<li>Vor Ausführung von <code>PduR_Init(ConfigPtr)</code> verbleibt das Modul in <code>PDUR_UNINIT</code>; Routing-Funktionen sind hierbei deaktiviert.</li>\n<li>Der Wechsel nach <code>PDUR_ONLINE</code> signalisiert die erfolgreiche Validierung und Übernahme der Konfiguration via <code>ConfigPtr</code>.</li>\n<li>Im Fehlerfall (<code>with error</code>) ist der reduzierte Modus <code>PDUR_REDUCED</code> einzunehmen.</li>\n<li>Ein System-Shutdown (<code>Shutdown</code>) ist aus jedem Zustand heraus zulässig und überführt die BSW-Komponente unmittelbar in den Abschlusszustand <code>PowerDown</code>.</li>\n</ul>"}, {"id": "FIG-92dc122cbf85f2a4", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm PduR</code>) zur Spezifikation des Zustandsmodells des AUTOSAR PDU Routers (PduR) im Schichtenmodell der AUTOSAR-Basissoftware (Communication Services). Es modelliert die Lebenszyklus- und Betriebsmodi der Komponente von der Systeminitialisierung bis zum Herunterfahren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält folgende Modellelemente:</p>\n<ul class=\"fig-list\">\n<li>Startzustand: <code>Powerup</code> (Initial-Pseudozustand)</li>\n<li>Zustände:</li>\n<li><code>PDUR_UNINIT</code>: Initialer Zustand nach dem Einschalten, uninitialisierter Zustand des Moduls</li>\n<li><code>PDUR_ONLINE</code>: Regulärer Betriebsmodus für volles Routing</li>\n<li><code>PDUR_REDUCED</code>: Eingeschränkter Betriebsmodus nach fehlerhafter Initialisierung</li>\n<li>Endzustand: <code>PowerDown</code> (Endzustand / System-Terminierung)</li>\n<li>Schnittstellen und Trigger:</li>\n<li>Initialisierungsfunktion <code>PduR_Init(ConfigPtr)</code> mit Fehlerunterscheidung (<code>without error</code>, <code>with error</code>)</li>\n<li>Ereignis <code>Shutdown</code></li>\n<li>Unmittelbarer Übergang <code>immediate</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss verläuft deterministisch über folgende Pfade:</p>\n<ol class=\"fig-list\">\n<li>Ausgehend von <code>Powerup</code> wechselt der PduR über den Übergang <code>immediate</code> direkt in den Zustand <code>PDUR_UNINIT</code>.</li>\n<li>Aus <code>PDUR_UNINIT</code> erfolgt der Aufruf von <code>PduR_Init(ConfigPtr)</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei fehlerfreier Initialisierung (<code>without error</code>) wechselt der PduR in den Zustand <code>PDUR_ONLINE</code>.</li>\n<li>Bei Auftreten eines Fehlers (<code>with error</code>) wechselt der PduR in den Zustand <code>PDUR_REDUCED</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Aus jedem der drei operativen Zustände (<code>PDUR_ONLINE</code>, <code>PDUR_UNINIT</code>, <code>PDUR_REDUCED</code>) führt ein auslösendes <code>Shutdown</code>-Ereignis direkt in den Endzustand <code>PowerDown</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindendes Zustandsverhalten für die Implementierung des AUTOSAR PDU Routers:</p>\n<ul class=\"fig-list\">\n<li>Vor Ausführung von <code>PduR_Init(ConfigPtr)</code> verbleibt das Modul in <code>PDUR_UNINIT</code>; Routing-Funktionen sind hierbei deaktiviert.</li>\n<li>Der Wechsel nach <code>PDUR_ONLINE</code> signalisiert die erfolgreiche Validierung und Übernahme der Konfiguration via <code>ConfigPtr</code>.</li>\n<li>Im Fehlerfall (<code>with error</code>) ist der reduzierte Modus <code>PDUR_REDUCED</code> einzunehmen.</li>\n<li>Ein System-Shutdown (<code>Shutdown</code>) ist aus jedem Zustand heraus zulässig und überführt die BSW-Komponente unmittelbar in den Abschlusszustand <code>PowerDown</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-55502a56dea0160b", "to": "FIG-92dc122cbf85f2a4", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
